"use client";

import { useState } from "react";
import { motion, useReducedMotion } from "framer-motion";
import { CaretLeftIcon as PhCaretLeft } from "@phosphor-icons/react";

function ChevronIcon({ flip }: { flip?: boolean }) {
  return <PhCaretLeft size={16} weight="bold" aria-hidden className={flip ? "rotate-180" : ""} />;
}

export function Pagination({ totalPages }: { totalPages: number }) {
  const [page, setPage] = useState(1);
  const shouldReduceMotion = useReducedMotion();

  return (
    <nav aria-label="Pagination" className="flex items-center gap-1">
      <button
        type="button"
        aria-label="Previous page"
        disabled={page === 1}
        onClick={() => setPage((p) => Math.max(1, p - 1))}
        className="inline-flex h-8 w-8 items-center justify-center rounded-lg text-slate-500 transition-colors hover:bg-slate-100 disabled:opacity-30 disabled:hover:bg-transparent focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-400 dark:hover:bg-slate-800"
      >
        <ChevronIcon flip />
      </button>
      {Array.from({ length: totalPages }, (_, i) => i + 1).map((n) => (
        <button
          key={n}
          type="button"
          aria-label={`Page ${n}`}
          aria-current={page === n ? "page" : undefined}
          onClick={() => setPage(n)}
          className={`relative inline-flex h-8 w-8 items-center justify-center rounded-lg text-sm font-medium transition-colors focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 ${
            page === n ? "text-white" : "text-slate-600 hover:bg-slate-100 dark:text-slate-300 dark:hover:bg-slate-800"
          }`}
        >
          {page === n && (
            <motion.span
              layoutId="pagination-active"
              className="absolute inset-0 rounded-lg bg-emerald-700"
              transition={shouldReduceMotion ? { duration: 0 } : { type: "spring", stiffness: 500, damping: 35 }}
            />
          )}
          <span className="relative">{n}</span>
        </button>
      ))}
      <button
        type="button"
        aria-label="Next page"
        disabled={page === totalPages}
        onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
        className="inline-flex h-8 w-8 items-center justify-center rounded-lg text-slate-500 transition-colors hover:bg-slate-100 disabled:opacity-30 disabled:hover:bg-transparent focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-600 dark:text-slate-400 dark:hover:bg-slate-800"
      >
        <ChevronIcon />
      </button>
    </nav>
  );
}
